+fn actual_top_k(graph: &Graph, k: usize) -> Vec<i64> {
+    let r = query(graph, &format!("{PFX}{CLAIM_QUERY}{k}")).unwrap();
+    r.rows.iter().map(|row| task_seq(row[0].as_ref().unwrap())).collect()
